// Sculpted Articulated 3D Indie Platformer Sky-Runner exported from Blender 5.2 LTS.
// 5184 verts, 10236 tris across 7 articulated parts:
//   0: Torso + Backpack + Scarf Collar | 1: Head + Hair + Aviator Goggles
//   2: Left Leg + Boot | 3: Right Leg + Boot | 4: Left Arm | 5: Right Arm | 6: Flowing Crimson Scarf Tail

export const RUNNER_PIVOTS = [
  [0.0, 0.98, 0.0],     // 0: Torso center
  [0.0, 1.38, 0.0],     // 1: Neck / Head
  [0.13, 0.72, 0.0],    // 2: Left Hip
  [-0.13, 0.72, 0.0],   // 3: Right Hip
  [0.31, 1.24, 0.0],    // 4: Left Shoulder
  [-0.31, 1.24, 0.0],   // 5: Right Shoulder
  [0.0, 1.32, -0.14],   // 6: Scarf Tail Neck Anchor
];

const RUNNER_V = "";
const RUNNER_I = "";

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

let cache = null;

export function getRunnerMesh() {
  if (cache) return cache;
  const raw = new Int16Array(b64ToBytes(RUNNER_V).buffer);
  const idx = new Uint16Array(b64ToBytes(RUNNER_I).buffer);
  const count = raw.length / 10;
  const pos = new Float32Array(count * 3);
  const norm = new Float32Array(count * 3);
  const col = new Float32Array(count * 3);
  const part = new Uint8Array(count);
  const rough = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const k = i * 10;
    pos[i * 3 + 0] = raw[k + 0] * 0.001;
    pos[i * 3 + 1] = raw[k + 1] * 0.001;
    pos[i * 3 + 2] = raw[k + 2] * 0.001;
    norm[i * 3 + 0] = raw[k + 3] * 0.001;
    norm[i * 3 + 1] = raw[k + 4] * 0.001;
    norm[i * 3 + 2] = raw[k + 5] * 0.001;
    col[i * 3 + 0] = raw[k + 6] * 0.001;
    col[i * 3 + 1] = raw[k + 7] * 0.001;
    col[i * 3 + 2] = raw[k + 8] * 0.001;
    const meta = raw[k + 9];
    part[i] = Math.floor(meta / 100);
    rough[i] = (meta % 100) * 0.01;
  }
  cache = { count, pos, norm, col, part, rough, idx };
  return cache;
}
